:root {
  --bg: #1e1e2f;
  --surface: #2a2a40;
  --text: #e0e0f0;
  --accent: #6c63ff;
  --accent-hover: #5a52e0;
  --card-back: #3a3a55;
  --card-front: #4a4a6a;
  --matched: #2e7d32;
  --radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 18px;
  line-height: 1.5;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 16px;
}

.game-container {
  background: var(--surface);
  border-radius: var(--radius);
  padding: 24px;
  max-width: 600px;
  width: 100%;
  box-shadow: 0 8px 24px rgba(0,0,0,0.3);
  display: flex;
  flex-direction: column;
  gap: 16px;
  align-items: center;
}

h1 {
  font-size: 1.8rem;
  text-align: center;
  color: var(--accent);
}

.instructions {
  text-align: center;
  font-size: 1rem;
  opacity: 0.8;
}

.status-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  width: 100%;
  gap: 16px;
  flex-wrap: wrap;
}

#move-counter {
  font-weight: 600;
  font-size: 1.1rem;
}

#new-game {
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: var(--radius);
  padding: 10px 20px;
  font-size: 1rem;
  font-family: var(--font);
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}

#new-game:hover {
  background: var(--accent-hover);
}

#new-game:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

#new-game:active {
  transform: scale(0.96);
}

.game-board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  width: 100%;
  aspect-ratio: 1 / 1;
  max-width: 500px;
}

.card {
  background: var(--card-back);
  border-radius: var(--radius);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  transition: background 0.2s, transform 0.1s;
  border: 2px solid transparent;
  user-select: none;
  aspect-ratio: 1 / 1;
}

.card:hover:not(.matched):not(.flipped) {
  background: var(--card-front);
}

.card:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.card.flipped {
  background: var(--card-front);
  cursor: default;
}

.card.matched {
  background: var(--matched);
  cursor: default;
  opacity: 0.7;
}

.card .card-content {
  visibility: hidden;
  font-size: 1.8rem;
}

.card.flipped .card-content,
.card.matched .card-content {
  visibility: visible;
}

.win-message {
  background: var(--accent);
  color: #fff;
  padding: 20px;
  border-radius: var(--radius);
  text-align: center;
  font-size: 1.3rem;
  font-weight: 600;
  width: 100%;
}

.win-message p {
  margin: 4px 0;
}

[hidden] {
  display: none !important;
}

@media (max-width: 400px) {
  .game-board {
    gap: 8px;
  }
  .card {
    font-size: 1.5rem;
  }
  .card .card-content {
    font-size: 1.5rem;
  }
  h1 {
    font-size: 1.5rem;
  }
  .status-bar {
    justify-content: center;
  }
}

(function () {
  'use strict';

  const COLORS = [
    '#e74c3c', '#3498db', '#2ecc71', '#f1c40f',
    '#9b59b6', '#e67e22', '#1abc9c', '#e84393'
  ];

  const board = document.getElementById('game-board');
  const moveCounter = document.getElementById('move-counter');
  const winMessage = document.getElementById('win-message');
  const finalMoves = document.getElementById('final-moves');
  const newGameBtn = document.getElementById('new-game');

  let deck = [];
  let flipped = [];
  let matchedPairs = 0;
  let moves = 0;
  let lockBoard = false;

  function shuffle(array) {
    for (let i = array.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [array[i], array[j]] = [array[j], array[i]];
    }
    return array;
  }

  function createDeck() {
    const pairs = COLORS.flatMap(color => [color, color]);
    return shuffle(pairs);
  }

  function renderBoard() {
    board.innerHTML = '';
    deck.forEach((color, index) => {
      const card = document.createElement('button');
      card.type = 'button';
      card.className = 'card';
      card.dataset.index = index;
      card.dataset.color = color;
      card.setAttribute('aria-label', 'Card ' + (index + 1) + ', face down');
      card.setAttribute('role', 'gridcell');

      const content = document.createElement('span');
      content.className = 'card-content';
      content.textContent = '●';
      content.style.color = color;

      card.appendChild(content);
      card.addEventListener('click', handleCardClick);
      board.appendChild(card);
    });
  }

  function handleCardClick(event) {
    const card = event.currentTarget;
    if (lockBoard) return;
    if (card.classList.contains('flipped') || card.classList.contains('matched')) return;

    card.classList.add('flipped');
    card.setAttribute('aria-label', 'Card ' + (parseInt(card.dataset.index) + 1) + ', face up');
    flipped.push(card);

    if (flipped.length === 2) {
      moves++;
      moveCounter.textContent = 'Moves: ' + moves;
      checkMatch();
    }
  }

  function checkMatch() {
    const [cardA, cardB] = flipped;
    if (cardA.dataset.color === cardB.dataset.color) {
      cardA.classList.add('matched');
      cardB.classList.add('matched');
      cardA.setAttribute('aria-label', 'Matched card');
      cardB.setAttribute('aria-label', 'Matched card');
      matchedPairs++;
      flipped = [];
      if (matchedPairs === COLORS.length) {
        endGame();
      }
    } else {
      lockBoard = true;
      setTimeout(() => {
        cardA.classList.remove('flipped');
        cardB.classList.remove('flipped');
        cardA.setAttribute('aria-label', 'Card ' + (parseInt(cardA.dataset.index) + 1) + ', face down');
        cardB.setAttribute('aria-label', 'Card ' + (parseInt(cardB.dataset.index) + 1) + ', face down');
        flipped = [];
        lockBoard = false;
      }, 800);
    }
  }

  function endGame() {
    finalMoves.textContent = moves;
    winMessage.hidden = false;
  }

  function resetGame() {
    deck = createDeck();
    flipped = [];
    matchedPairs = 0;
    moves = 0;
    lockBoard = false;
    moveCounter.textContent = 'Moves: 0';
    winMessage.hidden = true;
    renderBoard();
  }

  newGameBtn.addEventListener('click', resetGame);

  resetGame();
})();
